// src/hooks/UseLogs.js
import { useCallback, useEffect, useState } from 'react';
import { fetchLogs, fetchRecentLogs } from '../api/LogsApi';

/**
 * useLogs (명세형)
 * - 우선: GET /logs?page&size&from&to&keyword&aiLabel&eventType&sort
 * - fallback: GET /logs/recent?limit=
 */
export function useLogs(initialSize = 50) {
  const [size, setSize] = useState(initialSize);
  const [page, setPage] = useState(1);

  const [filters, setFilters] = useState({
    keyword: '',
    aiLabel: '', // DANGER | WARNING | SAFE | ''
    from: '',    // YYYY-MM-DD
    to: '',      // YYYY-MM-DD
    eventType: '',
    sort: 'collectedAt,desc',
  });

  const [logs, setLogs] = useState([]);
  const [total, setTotal] = useState(null); // /logs가 주면 total 채움
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const load = useCallback(
    async (override = {}) => {
      const q = {
        page: override.page ?? page,
        size: override.size ?? size,
        ...filters,
        ...(override.filters || {}),
      };

      setLoading(true);
      setError(null);

      try {
        const res = await fetchLogs(q);
        const items = Array.isArray(res) ? res : res?.items || [];
        setLogs(items);
        setTotal(res?.total ?? null);
      } catch (e) {
        try {
          const fallback = await fetchRecentLogs(q.size);
          setLogs(Array.isArray(fallback) ? fallback : []);
          setTotal(null);
        } catch (e2) {
          console.error('fetchLogs/fetchRecentLogs error:', e2);
          setError(e2);
        }
      } finally {
        setLoading(false);
      }
    },
    [page, size, filters]
  );

  useEffect(() => {
    load();
  }, [load]);

  const refresh = useCallback(() => load(), [load]);

  const search = useCallback(() => {
    setPage(1);
    load({ page: 1 });
  }, [load]);

  return {
    logs,
    loading,
    error,

    // pagination
    page,
    setPage,
    size,
    setSize,
    total,

    // 하위호환(예전 LogsPage가 limit/setLimit 쓰던 부분)
    limit: size,
    setLimit: setSize,

    // filters
    filters,
    setFilters,

    // actions
    refresh,
    search,
  };
}
